sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_burn;
uniform float amzp_centerX;
uniform float amzp_centerY;
uniform float amzp_seed;
uniform float amzp_irregular;
uniform float amzp_charWidth;
uniform float amzp_mainOn;
uniform float amzp_mainSize;
uniform float amzp_secondary;
uniform float amzp_spread;
uniform float amzp_secSize;
uniform float amzp_sizeVar;
uniform float amzp_secDelay;
layout(color) uniform half4 amzp_glowColor;
uniform float amzp_glow;
layout(color) uniform half4 amzp_coreColor;
uniform float amzp_core;
layout(color) uniform half4 amzp_charColor;
uniform float amzp_charAmount;
uniform float amzp_advScale;
uniform float amzp_advAngle;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float2 advF(float2 uv, float2 pv) { float2 W = layer; float2 q = advRot((uv - pv) * W, radians(amzp_advAngle)) / max(amzp_advScale, 0.01); return q / W + pv; }
    float2 advI(float2 pu, float2 pv) { float2 W = layer; float2 q = advRot((pu - pv) * W * max(amzp_advScale, 0.01), -radians(amzp_advAngle)); return q / W + pv; }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_autoSpeed * 0.5) : p; }
    float hh(float2 p) { return fract(sin(dot(p, float2(127.1, 311.7)) + amzp_seed * 3.91) * 43758.5453); }
    float vnoise(float2 p) {
        float2 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(hh(i), hh(i + float2(1.0, 0.0)), f.x), mix(hh(i + float2(0.0, 1.0)), hh(i + float2(1.0, 1.0)), f.x), f.y);
    }
    float fbm(float2 p) {
        float v = 0.0, a = 0.5;
        for (int i = 0; i < 5; i++) { v += a * vnoise(p); p = p * 2.03 + 11.7; a *= 0.5; }
        return v;
    }
    void amzRender() {
        float2 W = layer;
        float4 c = amzTexture(0, amzScreenNorm());
        float BURN = prog(amzp_burn);
        if (BURN <= 0.0) { amzOutput = c; return; }
        float2 asp = float2(W.x / W.y, 1.0);
        float2 cuv = float2(amzp_centerX, 1.0 - amzp_centerY);
        float2 p = advF(amzLayerNorm(), cuv) * asp;
        float2 cen = float2(amzp_centerX, 1.0 - amzp_centerY) * asp;
        float ns = clamp(floor(amzp_secondary + 0.5), 0.0, 24.0);
        float mainSp = max(amzp_mainSize, 0.05);
        float secSp = max(amzp_secSize, 0.05);
        float secMin = secSp * (1.0 - 0.6 * amzp_sizeVar);
        float pad = amzp_irregular * 0.25 + 0.05;
        float maxD = 0.0;
        maxD = max(maxD, length(advF(float2(0.0, 0.0), cuv) * asp - cen));
        maxD = max(maxD, length(advF(float2(1.0, 0.0), cuv) * asp - cen));
        maxD = max(maxD, length(advF(float2(0.0, 1.0), cuv) * asp - cen));
        maxD = max(maxD, length(advF(float2(1.0, 1.0), cuv) * asp - cen));
        float B;
        if ((amzp_mainOn>0.5)) B = (maxD + pad) / mainSp;
        else B = (length(asp) * 0.5 / max(amzp_advScale, 0.01) + pad) / secSp * (1.0 + amzp_secDelay * 0.5);
        if (!(amzp_mainOn>0.5) && ns < 0.5) { amzOutput = c; return; }
        float b = clamp(BURN, 0.0, 1.0) * B - 0.02;
        float n = fbm(p * 4.0) - 0.5;
        float nd = n * amzp_irregular * 0.45;
        float v = 1e6, spBest = 1.0;
        if ((amzp_mainOn>0.5)) {
            v = (length(p - cen) + nd) / mainSp;
            spBest = mainSp;
        }
        for (int i = 1; i < 25; i++) {
            float fi = float(i);
            if (fi > ns) break;
            float ang = 6.2831853 * hh(float2(fi, 1.0));
            float rad = amzp_spread * 0.7 * (0.3 + 0.7 * hh(float2(fi, 2.0)));
            float2 sc = cen + float2(cos(ang), sin(ang)) * rad;
            float sp = secSp * (1.0 - 0.6 * amzp_sizeVar * hh(float2(fi, 4.0)));
            float dly = amzp_secDelay * 0.5 * B * (0.2 + 0.8 * hh(float2(fi, 3.0)));
            float vi = (length(p - sc) + nd) / sp + dly;
            if (vi < v) { v = vi; spBest = sp; }
        }
        float dd = (v - b) * spBest;
        float cw = 0.02 + amzp_charWidth * 0.18;
        float hole = smoothstep(-0.01, 0.01, dd);
        float rim = exp(-pow(dd / 0.018, 2.0));
        float charA = 1.0 - smoothstep(0.0, cw, dd);
        if (BURN >= 0.999) { hole = 0.0; rim = 0.0; charA = 0.0; }
        float3 base = c.a > 0.0001 ? c.rgb / c.a : float3(0.0);
        float3 charCol = mix(base, amzp_charColor.rgb, clamp(charA * amzp_charAmount, 0.0, 1.0));
        float3 col = charCol + amzp_glowColor.rgb * rim * amzp_glow + amzp_coreColor.rgb * pow(rim, 4.0) * amzp_core;
        float a = c.a * max(hole, clamp(rim * amzp_glow, 0.0, 1.0) * 0.9) * (1.0 - smoothstep(0.96, 1.0, BURN));
        amzOutput = float4(clamp(col, 0.0, 1.0) * a, a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
